function toAbsence(row: typeof memberAbsences.$inferSelect): MemberAbsence {
  return {
    orgId: row.orgId as OrgId,
    userId: row.userId as UserId,
    delegateUserId: (row.delegateUserId ?? null) as UserId | null,
    startsAt: row.startsAt as IsoTimestamp,
    endsAt: row.endsAt as IsoTimestamp,
    note: row.note ?? null,
  };
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)))
    .get();
  return row ? toAbsence(row) : null;
}

/** Replaces any absence already stored for the member. */
export async function upsertAbsence(absence: MemberAbsence): Promise<MemberAbsence> {
  const db = getDb();
  db.delete(memberAbsences)
    .where(and(orgPredicate(memberAbsences.orgId, absence.orgId), eq(memberAbsences.userId, absence.userId)))
    .run();
  const row = db
    .insert(memberAbsences)
    .values({
      orgId: absence.orgId,
      userId: absence.userId,
      delegateUserId: absence.delegateUserId,
      startsAt: absence.startsAt,
      endsAt: absence.endsAt,
      note: absence.note,
    })
    .returning()
    .get();
  return toAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)))
    .run();
}

/** Drops `userId` as delegate from every absence in the org. */
export async function clearDelegate(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null })
    .where(and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.delegateUserId, userId)))
    .run();
}
